local serverProvider = require(script.Parent.WuKongServerProvider)
local optionsProvider = require(script.Parent.Parent.WuKongOptionsProvider)

return function()
	beforeEach(function()
		require(game.ReplicatedStorage.Packages.c2l)
	end)
	afterEach(function()
		serverProvider.Dispose()
	end)

	describe("wukong server provider options test", function()
		it("use default options", function()
			local server = serverProvider.BuildWuKongServer()
			expect(server).to.be.ok()
		end)

		it("create userContainer test", function()
			local options = optionsProvider.BuildDefaultOptions()
			local isCalled = false
			options.OnCreateUserContainer = function(userId: string)
				isCalled = true
			end
			local server = serverProvider.BuildWuKongServer(options)
			local userContainer = server:CreateWuKongContainer(1)
			-- create uc test
			expect(userContainer).to.be.ok()
			-- hander test
			expect(isCalled).to.equal(true)
		end)
	end)

	describe("wukong server extensions test", function()
		it("RegisterUser test", function()
			local server = serverProvider.BuildWuKongServer()
			local facade = server:RegisterUser(1)
			expect(facade).to.be.ok()
		end)
	end)
end
